@spec editor_verbs_spec  src=tests/specs/editor_verbs_spec.lua  loc=316  sha=18e9e47  cases=13
@exercises swingEditor (se), configManager (h.cm), temperEditor (te)
@surface   se:open, se:libraryDescriptor, cm:getAt, cm:defaultFor, te:libraryDescriptor
@harness   mk

# Intent
  Verb descriptors on the swing/temper editors under the library model:
  `publish` lifts a project copy into the shared library, `revert` discards
  project drift back to its source, `tidy` (swing only) drops pristine
  unreferenced project copies, and `reloadFactory` re-imports the shipped
  catalogue (silent adds, a confirm per divergent copy), and `importFactory`
  re-imports one entry (silent when non-divergent, a confirm when it diverges).
  Instantiated over a harness cm/ds with a lib
  service; imgui stubbed via package.preload. Recipe lifted from
  temperEditor_tree_spec.

# Helpers
  @fn mkLib(h)  @ 22-27
  @fn facadeStub()  @ 31-40
      -- Swing reaches the arrange/tracker services only for the reference scan and
      -- default-slot resolution; a leaf on each covers the descriptor path.
  @fn mkModalHost(captured)  @ 44-49
      -- modalHost stub: no-op registerKind, plus capture the last openConfirm args so
      -- the confirm-gated publish path is observable.
  @fn mkSwing(h)  @ 51-62
  @fn mkTemper(h, inUse)  @ 64-76

# Cases
  @case 'swing onPublish lifts a project copy into the library tier'  [harness]  @ 80-92
  @case 'swing onPublish confirms before overwriting a divergent library copy'  [harness]  @ 95-114
  @case 'swing onReloadFactory imports absent names silently and confirms per divergent copy'  [harness]  @ 117-141
  @case 'swing onImportFactory imports a non-divergent copy silently and confirms on divergence'  [harness]  @ 144-167
  @case 'temper onImportFactory imports a non-divergent copy silently and confirms on divergence'  [harness]  @ 170-190
  @case 'temper onPublish lifts a fresh project copy without confirming'  [harness]  @ 193-205
  @case 'temper onPublish confirms before overwriting a divergent library copy'  [harness]  @ 208-227
  @case 'swing onRevert restores a divergent project copy from its source'  [harness]  @ 230-243
  @case 'swing descriptor flags a divergent project row as modified'  [harness]  @ 246-257
  @case 'temper descriptor flags a divergent project row as modified'  [harness]  @ 260-271
  @case 'swing and temper descriptors both expose onTidy'  [harness]  @ 274-282
  @case 'swing onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 285-298
  @case 'temper onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 301-314

